import { Alert, ScrollView, StyleSheet, Text, TouchableOpacity, View } from 'react-native';
import { useNavigation } from '@react-navigation/core';

// FETCH URL CALLS
import axios from 'axios';

import { assessments, getQuestionsForAssessment } from '../data/algorithmAssessments';

const API_URL = 'http://192.168.1.94:5000';

const difficultyLabels = {
    beginner: 'Beginner',
    intermediate: 'Intermediate',
    advanced: 'Advanced',
};

const HomeScreen = () => {
    const [selectedAssessment, setSelectedAssessment] = useState(null);
    const [questionIndex, setQuestionIndex] = useState(0);
    const [score, setScore] = useState(0);
    const [selectedOption, setSelectedOption] = useState(null);
    const [isGameStarted, setIsGameStarted] = useState(false);
    const [isGameComplete, setIsGameComplete] = useState(false);
    const [timer, setTimer] = useState(0);

    const navigation = useNavigation();

    const questions = useMemo(
        () => getQuestionsForAssessment(selectedAssessment),
        [selectedAssessment]
    );

    useEffect(() => {
        if (!isGameStarted || isGameComplete) return undefined;

        const intervalId = setInterval(() => {
            setTimer((prevTime) => prevTime + 1);
        }, 1000);

        return () => clearInterval(intervalId);
    }, [isGameStarted, isGameComplete]);

    const startAssessment = (assessment) => {
        setSelectedAssessment(assessment);
        setQuestionIndex(0);
        setScore(0);
        setSelectedOption(null);
        setTimer(0);
        setIsGameComplete(false);
        setIsGameStarted(true);
    };

    const resetToAssessments = () => {
        setSelectedAssessment(null);
        setQuestionIndex(0);
        setScore(0);
        setSelectedOption(null);
        setTimer(0);
        setIsGameStarted(false);
        setIsGameComplete(false);
    };

    const endGame = async (finalScore, time) => {
        setIsGameComplete(true);

        try {
            const highScoreData = {
                username: 'sosai', // Replace with actual username when auth is wired in.
                score: finalScore,
                time,
                assessment: selectedAssessment?.title,
            };

            const response = await axios.post(`${API_URL}/add-highscore`, highScoreData);

            if (response.status === 200) {
                console.log('High score successfully posted.');
            }
        } catch (error) {
            console.log('Error posting high score:', error);
        }
    };

    const handleAnswerSelection = (selectedAnswerIndex) => {
        if (isGameComplete || selectedOption !== null) return;

        setSelectedOption(selectedAnswerIndex);

        const question = questions[questionIndex];
        const isCorrect = selectedAnswerIndex === question.correctAnswer;
        const nextScore = isCorrect ? score + 1 : score;
        setScore(nextScore);

        Alert.alert(
            isCorrect ? 'Correct!' : 'Incorrect',
            question.explanation,
            [
                {
                    text: questionIndex < questions.length - 1 ? 'Next' : 'Finish',
                    onPress: () => {
                        if (questionIndex < questions.length - 1) {
                            setQuestionIndex(questionIndex + 1);
                            setSelectedOption(null);
                        } else {
                            endGame(nextScore, timer);
                        }
                    },
                },
            ]
        );
    };

    if (!isGameStarted) {
        return (
            <ScrollView contentContainerStyle={styles.container}>
                <Text style={styles.title}>Codology Assessments</Text>
                <Text style={styles.subtitle}>
                    Choose a difficulty, language track, or full repo review. Questions were built from every algorithm found across the algos repo branches.
                </Text>

                <View style={styles.assessmentGrid}>
                    {assessments.map((assessment) => {
                        const count = getQuestionsForAssessment(assessment).length;

                        return (
                            <TouchableOpacity
                                key={assessment.id}
                                style={styles.assessmentCard}
                                onPress={() => startAssessment(assessment)}>
                                <Text style={styles.assessmentTitle}>{assessment.title}</Text>
                                <Text style={styles.assessmentSubtitle}>{assessment.subtitle}</Text>
                                <Text style={styles.assessmentCount}>{count} questions</Text>
                            </TouchableOpacity>
                        );
                    })}
                </View>
            </ScrollView>
        );
    }

    if (isGameComplete) {
        const percentage = questions.length ? Math.round((score / questions.length) * 100) : 0;

        return (
            <View style={styles.container}>
                <Text style={styles.title}>Assessment Complete</Text>
                <Text style={styles.scoreText}>{score}/{questions.length} correct ({percentage}%)</Text>
                <Text style={styles.metaText}>Time: {timer} seconds</Text>
                <Text style={styles.metaText}>Assessment: {selectedAssessment?.title}</Text>

                <TouchableOpacity style={styles.primaryButton} onPress={() => startAssessment(selectedAssessment)}>
                    <Text style={styles.buttonText}>Retry Assessment</Text>
                </TouchableOpacity>
                <TouchableOpacity style={styles.secondaryButton} onPress={resetToAssessments}>
                    <Text style={styles.buttonText}>Choose Another Assessment</Text>
                </TouchableOpacity>
            </View>
        );
    }

    const question = questions[questionIndex];

    if (!question) {
        return (
            <View style={styles.container}>
                <Text style={styles.title}>No questions found.</Text>
                <TouchableOpacity style={styles.primaryButton} onPress={resetToAssessments}>
                    <Text style={styles.buttonText}>Back to Assessments</Text>
                </TouchableOpacity>
            </View>
        );
    }

    return (
        <ScrollView contentContainerStyle={styles.container}>
            <View style={styles.quizHeader}>
                <Text style={styles.timer}>Time: {timer}s</Text>
                <Text style={styles.progress}>Question {questionIndex + 1}/{questions.length}</Text>
                <Text style={styles.score}>Score: {score}</Text>
            </View>

            <Text style={styles.assessmentPill}>{selectedAssessment?.title}</Text>
            <Text style={styles.difficultyPill}>{difficultyLabels[question.difficulty]} • {question.language} • {question.category}</Text>
            <Text style={styles.questionText}>{question.prompt}</Text>
            <Text style={styles.sourceText}>Source: {question.sourcePath} ({question.branches.join(', ')})</Text>

            <View style={styles.optionsContainer}>
                {question.options.map((option, index) => {
                    const isSelected = selectedOption === index;
                    const isCorrect = question.correctAnswer === index;

                    return (
                        <TouchableOpacity
                            key={`${question.id}-${option}`}
                            style={[
                                styles.optionButton,
                                isSelected && styles.buttonSelected,
                                selectedOption !== null && isCorrect && styles.buttonCorrect,
                            ]}
                            onPress={() => handleAnswerSelection(index)}>
                            <Text style={styles.buttonText}>{option}</Text>
                        </TouchableOpacity>
                    );
                })}
            </View>

            <TouchableOpacity style={styles.quitButton} onPress={resetToAssessments}>
                <Text style={styles.quitButtonText}>Exit Assessment</Text>
            </TouchableOpacity>
        </ScrollView>
    );
};

const styles = StyleSheet.create({
    container: {
        flexGrow: 1,
        alignItems: 'center',
